import numpy as np


def _radii_from_centers(centers):
    n = len(centers)
    radii = np.empty(n)
    for i in range(n):
        x, y = centers[i]
        r = min(x, y, 1.0 - x, 1.0 - y)
        for j in range(n):
            if j == i:
                continue
            dx = centers[i][0] - centers[j][0]
            dy = centers[i][1] - centers[j][1]
            d = (dx*dx + dy*dy) ** 0.5
            r = min(r, d / 2.0)
        radii[i] = r
    return radii


def _packing_score(centers):
    return float(np.sum(_radii_from_centers(centers)))


def _grid55_plus1():
    pts = []
    for i in range(5):
        for j in range(5):
            pts.append([0.1 + i * 0.2, 0.1 + j * 0.2])
    pts.append([0.5, 0.5])
    return np.array(pts)


def _rows(config):
    n = sum(config)
    n_rows = len(config)
    dy = 1.0 / (n_rows + 1)
    centers = np.zeros((n, 2))
    idx = 0
    for r in range(n_rows):
        k = config[r]
        y = dy * (r + 1)
        if k > 1:
            xs = np.linspace(0.1, 0.9, k)
        else:
            xs = np.array([0.5])
        for x in xs:
            centers[idx] = [x, y]
            idx += 1
    return centers


def construct_packing():
    candidates = []

    # F1: dense 5x5 grid + center
    g = _grid55_plus1()
    candidates.append(g)

    # Layered rows
    for cfg in [[5, 5, 5, 5, 5, 1], [4, 5, 5, 5, 5, 2], [3, 5, 5, 5, 5, 3]]:
        candidates.append(_rows(cfg))

    # F3: mixed radii — shrink the 4 corner circles of the grid so
    # edge/circle radii can grow; recompute all radii from the rule.
    for f in [0.85, 0.75, 0.65]:
        gc = g.copy()
        for (i, j) in [(0, 0), (4, 0), (0, 4), (4, 4)]:
            x, y = gc[i * 5 + j]
            cx, cy = 0.5, 0.5
            gc[i * 5 + j] = [cx + (x - cx) * f, cy + (y - cy) * f]
        candidates.append(gc)

    # F4: targeted perturb of the base grid — nudge a few circles toward
    # the wall with the most slack, recompute radii.
    for (i, j, dx, dy) in [(0, 0, -0.02, -0.02), (4, 4, 0.02, 0.02),
                           (2, 0, 0.0, -0.02), (2, 4, 0.0, 0.02)]:
        pc = g.copy()
        x, y = pc[i * 5 + j]
        pc[i * 5 + j] = [x + dx, y + dy]
        candidates.append(pc)

    best = None
    best_sum = -1.0
    for cand in candidates:
        s = _packing_score(cand)
        if s > best_sum:
            best_sum = s
            best = cand

    radii = _radii_from_centers(best)
    return best, radii, float(np.sum(radii))

