            row = np.zeros(n)
            row[i] = 1
            row[j] = 1
            A_rows.append(row)
            b_vals.append(d)
    for i in range(n):
        x, y = centers[i]
        b_dist = min(x, y, 1 - x, 1 - y)
        row = np.zeros(n)
        row[i] = 1
        A_rows.append(row)
        b_vals.append(b_dist)
    A = np.array(A_rows)
    b = np.array(b_vals)
    bounds = [(0, None)] * n
    result = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
    if result.success:
        return np.maximum(result.x, 0)
    return _radii_fallback(centers)


def _radii_fallback(centers):
    n = len(centers)
    radii = np.array([min(x, y, 1 - x, 1 - y) for x, y in centers])
    for _ in range(300):
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
                s = radii[i] + radii[j]
                if s > dist and s > 0:
                    scale = dist / s
                    radii[i] *= scale
                    radii[j] *= scale
    return radii


def _hex_lattice(s):
    dy = s * np.sqrt(3) / 2
    pts = []
    row = 0
    y = 0.02
    while y <= 0.98:
        x_offset = (s / 2) if (row % 2 == 1) else 0
        x = 0.02 + x_offset
        while x <= 0.98:
            pts.append([x, y])
            x += s
        y += dy
        row += 1
    return np.array(pts)


def _select(pts, k=26):
    dists = np.sqrt((pts[:, 0] - 0.5) ** 2 + (pts[:, 1] - 0.5) ** 2)
    idx = np.argsort(dists)
    return pts[idx[:k]].copy()


def construct_packing():
    candidates = []
    for s in [0.21, 0.22, 0.23, 0.24]:
        pts = _hex_lattice(s)
        if len(pts) >= 26:
            candidates.append(_select(pts))
    best = None
    best_sum = -1.0
    for cand in candidates:
        radii = _radii_lp(cand)
        s = float(np.sum(radii))
        if s > best_sum:
            best_sum = s
            best = cand
            best_radii = radii
    return best, best_radii, best_sum

