import numpy as np
from scipy.optimize import linprog, minimize


def _radii_lp(centers):
    n = len(centers)
    c = -np.ones(n)
    A_rows = []
    b_vals = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
            row = np.zeros(n)
            row[i] = 1
            row[j] = 1
            A_rows.append(row)
            b_vals.append(d)
    for i in range(n):
        x, y = centers[i]
        b_dist = min(x, y, 1 - x, 1 - y)
        row = np.zeros(n)
        row[i] = 1
        A_rows.append(row)
        b_vals.append(b_dist)
    A = np.array(A_rows)
    b = np.array(b_vals)
    bounds = [(0, None)] * n
    result = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
    if result.success:
        return np.maximum(result.x, 0)
    return _radii_fallback(centers)


def _radii_fallback(centers):
    n = len(centers)
    radii = np.array([min(x, y, 1 - x, 1 - y) for x, y in centers])
    for _ in range(300):
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
                s = radii[i] + radii[j]
                if s > dist and s > 0:
                    scale = dist / s
                    radii[i] *= scale
                    radii[j] *= scale
    return radii


def _lp_sum(centers):
    return float(np.sum(_radii_lp(centers)))


def _grid55_plus1():
    pts = []
    for i in range(5):
        for j in range(5):
            pts.append([0.1 + i * 0.2, 0.1 + j * 0.2])
    pts.append([0.5, 0.5])
    return np.array(pts)


def _rows(config):
    n = sum(config)
    n_rows = len(config)
    dy = 1.0 / (n_rows + 1)
    centers = np.zeros((n, 2))
    idx = 0
    for r in range(n_rows):
        k = config[r]
        y = dy * (r + 1)
        if k > 1:
            xs = np.linspace(0.1, 0.9, k)
        else:
            xs = np.array([0.5])
        for x in xs:
            centers[idx] = [x, y]
            idx += 1
    return centers


def _optimize(init, maxiter=120):
    result = minimize(
        lambda x: -_lp_sum(x.reshape(26, 2)),
        init.flatten(),
        method='L-BFGS-B',
        bounds=[(0.02, 0.98)] * 52,
        options={'maxiter': maxiter, 'ftol': 1e-9},
    )
    return result.x.reshape(26, 2)


def construct_packing():
    inits = [_grid55_plus1(),
             _rows([5, 5, 5, 5, 5, 1]),
             _rows([4, 5, 5, 5, 5, 2])]
    best_centers = None
    best_sum = -1.0
    for init in inits:
        # baseline: no optimization
        radii = _radii_lp(init)
        s = float(np.sum(radii))
        if s > best_sum:
            best_sum, best_centers, best_radii = s, init.copy(), radii
        # optimized
        opt = _optimize(init, maxiter=120)
        radii = _radii_lp(opt)
        s = float(np.sum(radii))
        if s > best_sum:
            best_sum, best_centers, best_radii = s, opt.copy(), radii
    return best_centers, best_radii, best_sum

