    return _radii_fallback(centers)


def _radii_fallback(centers):
    n = len(centers)
    radii = np.array([min(x, y, 1 - x, 1 - y) for x, y in centers])
    for _ in range(300):
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
                s = radii[i] + radii[j]
                if s > dist and s > 0:
                    scale = dist / s
                    radii[i] *= scale
                    radii[j] *= scale
    return radii


def _grid55_plus1():
    pts = []
    for i in range(5):
        for j in range(5):
            pts.append([0.1 + i * 0.2, 0.1 + j * 0.2])
    pts.append([0.5, 0.5])
    return np.array(pts)


def _rows(config):
    n = sum(config)
    n_rows = len(config)
    dy = 1.0 / (n_rows + 1)
    centers = np.zeros((n, 2))
    idx = 0
    for r in range(n_rows):
        k = config[r]
        y = dy * (r + 1)
        if k > 1:
            xs = np.linspace(0.1, 0.9, k)
        else:
            xs = np.array([0.5])
        for x in xs:
            centers[idx] = [x, y]
            idx += 1
    return centers


def _smooth_obj_and_grad(centers, r):
    """Sum of LP radii as a smooth min-sum. Returns (value, grad)."""
    n = len(centers)
    d = np.zeros((n, n))
    for i in range(n):
        for j in range(i + 1, n):
            dd = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
