            elif (1 - y) == wall:
                g[1] = -1.0
            grad[i] += g
        else:
            # neighbor arg binds: push i away from arg
            dd = d[i, arg]
            if dd > 1e-9:
                grad[i] += (centers[i] - centers[arg]) / dd
    return val, grad


def _gradient_optimize(centers, steps=400, lr=0.004):
    c = centers.copy()
    r = _radii_lp(c)
    for t in range(steps):
        val, grad = _smooth_obj_and_grad(c, r)
        c = c + lr * grad
        c = np.clip(c, 0.02, 0.98)
        if (t + 1) % 20 == 0:
            r = _radii_lp(c)
    return c


def construct_packing():
    base = _grid55_plus1()
